import type { MessageKey } from '../hooks/useTranslation';

/**
 * Ключи каталога — самому react-intl.
 *
 * `MessageDescriptor.id` объявлен в `@formatjs/intl` не строкой, а выводом из
 * пустого глобального интерфейса `FormatjsIntl.Message`: не объявишь ключи —
 * получишь `string`. Поэтому `t('...')` подсказывал варианты (там union наш, из
 * `useTranslation`), а `{ id: '...' }` — нет.
 *
 * Объявленные здесь, ключи достаются всем дескрипторам разом: настройкам тостов
 * у эндпоинта (`showSuccessMessage`, `hideErrorMessage`), подписи маршрута
 * (`labelId`) и любому будущему месту, где ключ едет данными. Обёртки вроде
 * `papiMessage` для этого больше не нужны — та осталась в ядре по другой
 * причине: она сверяет ключ со **своим** каталогом, не давая строке ядра
 * случайно сослаться на строку панели.
 *
 * Файл на стороне панели, а не ядра: каталог принадлежит ей. Ядро читает
 * результат через `MessageId` и без этого объявления работает по-старому — с
 * обычной строкой.
 *
 * Обратная сторона — ядро теперь ждёт, что `MessageKey` включает и его ключи.
 * Так и есть (см. `hooks/useTranslation.ts`), а если перестанет — сломается
 * сборка, а не интерфейс.
 */
declare global {
  namespace FormatjsIntl {
    interface Message {
      ids: MessageKey;
    }
  }
}
